def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    """Power-law model for log10(|ID|/A) using both gate and drain voltages."""

    a, b, c, d = parameters  # Placing 4 parameters in the order of appearance in the equation.
    log_idot_a = a * (gate_voltage_abs ** b) * (drain_voltage_abs ** c) * (gate_voltage_abs + drain_voltage_abs) ** d
    return np.log10(log_idot_a)  # Ensure the output is in the desired unit (log10(|ID|/A))
